{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue WIN 35,428, sharing the tropane N-methyl carbomethoxy core, was confirmed by in vivo autoradiography in monkeys to cross the blood-brain barrier and label dopamine transporters, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "β-CIT, a close cocaine analogue, showed 5.5% of injected radioactivity in cynomolgus monkey brain at 10 minutes after IV injection by PET, demonstrating high brain uptake despite a basic tropane nitrogen.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "β-CIT-FP, another close analogue, reached 6% of total injected radioactivity in cynomolgus monkey brain by PET, confirming efficient BBB passage for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "PE2I, a related tropane cocaine analogue, showed favorable brain distribution in humans with 6% of radioactivity in the brain after IV injection, providing human evidence for meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The tropane analogue MCL-322 showed fast entry into rat brain and high striatal accumulation in PET studies, further supporting the ability of this scaffold to penetrate the BBB after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is cocaine, and multiple close tropane analogues with the same N-methyl carbomethoxy core consistently demonstrate high brain uptake in monkeys, rats, and humans after systemic administration. Direct experimental evidence overrides the physicochemical prior suggesting low passive permeability due to ionization.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma ratio for cocaine itself is included in the provided records, but the analogue PET and biodistribution data are strong and directly transferable.",
    "Efflux transporter involvement was not directly measured in the cited records, but the observed high brain uptake indicates adequate net CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

